"""`.Normal detail map blending`: generated by export_nodes.py from library.blend; kept by hand from then on."""

NAME = '.Normal detail map blending'
KIND = 'ShaderNodeTree'


def build(lib):
    t = lib.new_group(NAME, KIND, props={})

    t.socket('OUTPUT', 'Result', 'NodeSocketColor', default_value=(0.0, 0.0, 0.0, 0.0))
    t.socket('INPUT', 'Normal alpha (X and Y)', 'NodeSocketColor')
    t.socket('INPUT', 'Normal detail alpha (X and Y)', 'NodeSocketColor')
    t.socket('INPUT', 'Normal Alpha', 'NodeSocketFloat', min_value=0.0, max_value=1.0)
    t.socket('INPUT', 'NormalD Alpha', 'NodeSocketFloat')
    t.socket('INPUT', 'Use whiteout method or Unity tech demo? (whiteout = 1)', 'NodeSocketFloat', subtype='FACTOR', default_value=0.5, min_value=0.0, max_value=1.0)

    t.node('NodeGroupOutput', 'Group Output', props={
        'location': (395.91418, 0.0),
    })
    t.node('ShaderNodeMix', 'Mix', inputs={'Factor_Float': 0.5}, outputs={'Result_Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (205.91418, 47.41008),
        'data_type': 'RGBA',
    })
    t.node('ShaderNodeGroup', 'Group.002', props={
        'node_tree': lib.group('.Normal map parsing (Unity tech demo)'),
        'location': (-205.83875, 125.02758),
        'width': 329.03925,
    })
    t.node('NodeGroupInput', 'Group Input', props={
        'location': (-603.4141, 0.0),
        'width': 337.49994,
    })
    t.node('ShaderNodeGroup', 'Group.003', props={
        'node_tree': lib.group('.Normal parsing (whiteout method)'),
        'location': (-205.91418, -47.410095),
        'width': 332.816,
    })

    t.link('Group.002', 'Image', 'Mix', 'A_Color')
    t.link('Group.003', 'Color', 'Mix', 'B_Color')
    t.link('Group Input', 'Normal alpha (X and Y)', 'Group.003', 'Normal alpha (X and Y)')
    t.link('Group Input', 'Normal alpha (X and Y)', 'Group.002', 'Normal')
    t.link('Group Input', 'Normal Alpha', 'Group.002', 'Normal Alpha')
    t.link('Group Input', 'Normal detail alpha (X and Y)', 'Group.003', 'Normal detail alpha (X and Y)')
    t.link('Group Input', 'Normal detail alpha (X and Y)', 'Group.002', 'NormalD')
    t.link('Group Input', 'NormalD Alpha', 'Group.002', 'NormalD Alpha')
    t.link('Mix', 'Result_Color', 'Group Output', 'Result')
    t.link('Group Input', 'Use whiteout method or Unity tech demo? (whiteout = 1)', 'Mix', 'Factor_Float')
    return t
